86	// Levenshtein distance for fuzzy matching
87	function levenshteinDistance(a: string, b: string): number {
88	  const matrix: number[][] = [];
89	  for (let i = 0; i <= b.length; i++) {
90	    matrix[i] = [i];
91	  }
92	  for (let j = 0; j <= a.length; j++) {
93	    matrix[0][j] = j;
94	  }
95	  for (let i = 1; i <= b.length; i++) {
96	    for (let j = 1; j <= a.length; j++) {
97	      if (b.charAt(i - 1) === a.charAt(j - 1)) {
98	        matrix[i][j] = matrix[i - 1][j - 1];
99	      } else {
100	        matrix[i][j] = Math.min(
101	          matrix[i - 1][j - 1] + 1,
102	          matrix[i][j - 1] + 1,
103	          matrix[i - 1][j] + 1,
104	        );
105	      }
106	    }
107	  }
108	  return matrix[b.length][a.length];
109	}
