111	// Check if spoken answer matches the correct answer (fuzzy matching)
112	function checkAnswer(spoken: string, correct: string): boolean {
113	  const normalizedSpoken = normalizeText(spoken);
114	  const normalizedCorrect = normalizeText(correct);
115	
116	  // Exact match
117	  if (normalizedSpoken === normalizedCorrect) return true;
118	
119	  // Check if spoken contains the answer
120	  if (normalizedSpoken.includes(normalizedCorrect)) return true;
121	  if (
122	    normalizedCorrect.includes(normalizedSpoken) &&
123	    normalizedSpoken.length > 3
124	  )
125	    return true;
126	
127	  // Check similarity (allow for small speech recognition errors)
128	  const spokenWords = normalizedSpoken.split(" ");
129	  const correctWords = normalizedCorrect.split(" ");
130	
131	  // Count matching words
132	  let matches = 0;
133	  for (const word of correctWords) {
134	    if (
135	      spokenWords.some(
136	        (sw) =>
137	          sw === word ||
138	          (sw.length > 3 &&
139	            word.length > 3 &&
140	            (sw.includes(word) ||
141	              word.includes(sw) ||
142	              levenshteinDistance(sw, word) <= Math.floor(word.length / 3))),
143	      )
144	    ) {
145	      matches++;
146	    }
147	  }
148	
149	  // If most words match, consider it correct
150	  return matches >= Math.ceil(correctWords.length * 0.7);
151	}
