153	// Generate valid groupings for 9 consonants (2-3 spaces, groups of 2+ letters)
154	function generateGrouping(): number[] {
155	  // Valid groupings for 9 consonants with 2-3 spaces, all groups >= 2
156	  const validGroupings = [
157	    [2, 2, 2, 3], // MS SN GV WLS
158	    [2, 2, 3, 2], // MS SN GVW LS
159	    [2, 3, 2, 2], // MS SNG VW LS
160	    [3, 2, 2, 2], // MSS NG VW LS
161	    [3, 3, 3], // MSS NGV WLS
162	    [3, 2, 4], // MSS NG VWLS
163	    [2, 3, 4], // MS SNG VWLS
164	    [4, 3, 2], // MSSN GVW LS
165	    [2, 4, 3], // MS SNGV WLS
166	    [3, 4, 2], // MSS NGVW LS
167	  ];
168	  return validGroupings[Math.floor(Math.random() * validGroupings.length)];
169	}
