171	// Animated title component for the menu screen
172	function AnimatedTitle(): React.ReactElement {
173	  const [phase, setPhase] = useState<
174	    "full" | "fading" | "collapsed" | "condensed"
175	  >("full");
176	
177	  // Original title
178	  const fullText = "MISSING VOWELS";
179	  const vowels = new Set(["A", "E", "I", "O", "U"]);
180	
181	  // Generate random grouping once on mount
182	  const grouping = useMemo(() => generateGrouping(), []);
183	
184	  useEffect(() => {
185	    // 1s: start fading vowels (0.5s fade)
186	    const fadeTimer = setTimeout(() => setPhase("fading"), 1000);
187	    // 1.5s: collapse vowels to zero width
188	    const collapseTimer = setTimeout(() => setPhase("collapsed"), 1500);
189	    // 1.9s: add spaces between groups
190	    const condenseTimer = setTimeout(() => setPhase("condensed"), 1900);
191	    return () => {
192	      clearTimeout(fadeTimer);
193	      clearTimeout(collapseTimer);
194	      clearTimeout(condenseTimer);
195	    };
196	  }, []);
197	
198	  // Build consonant positions from grouping
199	  const consonantPositions = useMemo(() => {
200	    const positions: { group: number; pos: number }[] = [];
201	    let idx = 0;
202	    for (let g = 0; g < grouping.length; g++) {
203	      for (let p = 0; p < grouping[g]; p++) {
204	        positions.push({ group: g, pos: p });
205	        idx++;
206	      }
207	    }
208	    return positions;
209	  }, [grouping]);
210	
211	  // Build letter elements with animation classes
212	  const letters = useMemo(() => {
213	    const result: React.ReactElement[] = [];
214	    let consonantIndex = 0;
215	
216	    for (let i = 0; i < fullText.length; i++) {
217	      const char = fullText[i];
218	
219	      if (char === " ") {
220	        result.push(
221	          <span
222	            key={i}
223	            className={`title-space ${phase === "collapsed" || phase === "condensed" ? "hidden" : ""}`}
224	          >
225	            {" "}
226	          </span>,
227	        );
228	      } else if (vowels.has(char)) {
229	        const vowelClass =
230	          phase === "full" ? "" : phase === "fading" ? "fade-out" : "collapse";
231	        result.push(
232	          <span key={i} className={`title-letter title-vowel ${vowelClass}`}>
233	            {char}
234	          </span>,
235	        );
236	      } else {
237	        const posInfo = consonantPositions[consonantIndex];
238	        const isGroupStart = posInfo.pos === 0 && posInfo.group > 0;
239	        consonantIndex++;
240	
241	        result.push(
242	          <span
243	            key={i}
244	            className={`title-letter title-consonant ${isGroupStart && phase === "condensed" ? "group-start" : ""}`}
245	          >
246	            {char}
247	          </span>,
248	        );
249	      }
250	    }
251	
252	    return result;
253	  }, [phase, consonantPositions]);
254	
255	  return <h1 className="animated-title">{letters}</h1>;
256	}
